import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.D6W-aSwD.js";const n="/Stable_V5.1/assets/app_log_viewer.Cc04db9F.jpg",u=JSON.parse('{"title":"Console Logging","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/troubleshooting/console_logging.md","filePath":"en/qgc-user-guide/troubleshooting/console_logging.md"}'),s={name:"en/qgc-user-guide/troubleshooting/console_logging.md"};function l(r,e,g,d,p,c){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="console-logging" tabindex="-1">Console Logging <a class="header-anchor" href="#console-logging" aria-label="Permalink to &quot;Console Logging&quot;">​</a></h1><p>The <em>App Log Viewer</em> can be a helpful tool for diagnosing <em>QGroundControl</em> problems. It can be found in <strong>Application Settings &gt; App Log Viewer</strong>.</p><p><img src="'+n+`" alt="App Log Viewer"></p><p>Click the <strong>Categories</strong> button to enable/disable the logging categories displayed by <em>QGroundControl</em>.</p><h2 id="common-logging-categories" tabindex="-1">Common Logging Categories <a class="header-anchor" href="#common-logging-categories" aria-label="Permalink to &quot;Common Logging Categories&quot;">​</a></h2><p>The most commonly used logging categories are listed below.</p><table tabindex="0"><thead><tr><th>Category(s)</th><th>Description</th></tr></thead><tbody><tr><td><code>Comms.LinkManager</code>, <code>Vehicle.MultiVehicleManager</code></td><td>Debug connection problems.</td></tr><tr><td><code>Comms.LinkManager:verbose</code></td><td>Debug serial ports not being detected. Very noisy continuous output of available serial ports.</td></tr><tr><td><code>VehicleSetup.FirmwareUpgrade</code></td><td>Debug firmware flash issues.</td></tr><tr><td><code>FactSystem.ParameterManager</code></td><td>Debug parameter load problems.</td></tr><tr><td><code>FactSystem.ParameterManager:debugCacheFailure</code></td><td>Debug parameter cache crc misses.</td></tr><tr><td><code>PlanManager.PlanManager</code>, <code>PlanManager.MissionManager</code>, <code>PlanManager.GeoFenceManager</code>, <code>PlanManager.RallyPointManager</code></td><td>Debug Plan upload/download issues.</td></tr><tr><td><code>AutoPilotPlugins.RadioComponentController</code></td><td>Debug Radio calibration issues.</td></tr></tbody></table><h2 id="logging-from-the-command-line" tabindex="-1">Logging from the Command Line <a class="header-anchor" href="#logging-from-the-command-line" aria-label="Permalink to &quot;Logging from the Command Line&quot;">​</a></h2><p>An alternate mechanism for logging is using the <code>--logging</code> command line option. This is handy if you are trying to get logs from a situation where <em>QGroundControl</em> crashes.</p><p>How you do this and where the traces are output vary by OS:</p><ul><li><p>Windows</p><ul><li><p>You must open a command prompt, change directory to the <strong>qgroundcontrol.exe</strong> location, and run it from there:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\\Program Files (x86)\\qgroundcontrol&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qgroundcontrol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span></span></code></pre></div></li><li><p>When <em>QGroundControl</em> starts you should see a separate console window open which will have the log output</p></li></ul></li><li><p>OSX</p><ul><li><p>You must run <em>QGroundControl</em> from Terminal. The Terminal app is located in Applications/Utilities. Once Terminal is open paste the following into it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/qgroundcontrol.app/Contents/MacOS/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./qgroundcontrol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span></span></code></pre></div></li><li><p>Log traces will output to the Terminal window.</p></li></ul></li><li><p>Linux</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./qgroundcontrol-start.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span></span></code></pre></div><ul><li>Log traces will output to the shell you are running from.</li></ul></li></ul>`,11)]))}const m=o(s,[["render",l]]);export{u as __pageData,m as default};
